command:
$ErrorActionPreference="Stop"
Set-Location $env:FLYEXPLORER_CANONICAL_CHECKOUT
git fetch origin main work/search-v3-indexed-filename-20261008 --no-tags
if($LASTEXITCODE -ne 0){throw "fetch"}
git switch --detach ffc2466be51c32c1cf7454a2df80fe4f8c3f5f99
if($LASTEXITCODE -ne 0){throw "checkout"}
try {
 .\test.bat policy
 if($LASTEXITCODE -ne 0){throw "policy"}
 git diff --check 387efa622f6a9ce6685e3bffb98299df0503de3c ffc2466be51c32c1cf7454a2df80fe4f8c3f5f99
 if($LASTEXITCODE -ne 0){throw "whitespace"}
 $files=Get-ChildItem logs\search-v3-indexed -File -Filter "*.bmp" -ErrorAction SilentlyContinue
 foreach($file in $files){ Write-Host ("INDEXED_VISUAL_FILE="+$file.FullName+" SIZE="+$file.Length) }
 Write-Host "SEARCH_V3_INDEXED_DOCS_POLICY=PASS"
} finally {
 git switch main
 if($LASTEXITCODE -ne 0){throw "restore"}
}
